E1.css:
[data-ui-unit="E1"].trip-header {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  align-items: center;
  height: 62px;
  width: 100%;
}

[data-ui-unit="E1"].trip-header button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin: 0;
  padding: 0;
  background: transparent;
  border: none;
  cursor: pointer;
  color: inherit;
  font: inherit;
}

[data-ui-unit="E1"].trip-header button img {
  width: 24px;
  height: 24px;
  display: block;
  opacity: 1;
}

[data-ui-unit="E1"].trip-header h1 {
  grid-column: 2;
  margin: 0;
  font-size: 18px;
  line-height: 26px;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

[data-ui-unit="E1"].trip-header span[aria-hidden="true"] {
  grid-column: 3;
  display: block;
  width: 44px;
  height: 44px;
}

@media (max-width: 360px) {
  [data-ui-unit="E1"].trip-header h1 {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
  }
}

E2.css:
[data-ui-unit="E2"].day-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 26px;
}

[data-ui-unit="E2"].day-tabs button {
  min-width: 64px;
  height: 32px;
  padding: 0 12px;
  border-radius: 16px;
  border: 1px solid #e8e8e8;
  background-color: #ffffff;
  color: #111111;
  font-weight: 700;
  font-size: 14px;
  line-height: 1;
  cursor: default;
  transition: none;
}


[data-ui-unit="E2"].day-tabs button[aria-pressed="true"] {
  background-color: #111111;
  color: #ffffff;
  border-color: #111111;
}


[data-ui-unit="E2"].day-tabs button:disabled {
  opacity: 1; 
}
